		public override void update()
		{
			base.update();
			if (player.x > 160 && player.x < 480)
			{
				narratorFollow.x = player.x - 90;
				narratorFollow2.x = player.x - 90;
			}

			FlxG.collide(level, cheerleader);
			if (player.y > 475)
			{
				FlxG.overlap<Cheerleader, Machine>(cheerleader, machineForCheerleader, cheerleaderOverlappedWithMachine);
			}
		}

		public override void getWell()
		{
			FlxG.bgColor = 4281241856;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new AnimationHans(scale, false));
		}
	}
